    public void testIsIndependentOf_SecondConditionTrue() {
        // Setup existing node to populate typesInSet
        Property existingProp = mock(Property.class);
        existingProp.typesSet = Collections.singleton("TypeA");
        subGraph.addNode(existingProp);

        // Setup target prop
        Property prop = mock(Property.class);
        prop.type = "TypeB";
        prop.typesSet = Collections.singleton("TypeB"); // No intersection with TypeA

        // Mock getRelated(prop.type) to return a set that intersects with typesInSet (TypeA)
