        // Branch 1: intersects(prop.typesSet) is true
        Property p1 = mock(Property.class);
        Property p2 = mock(Property.class);
        p2.typesSet = Collections.singleton("A");
        subGraph.addNode(p2);
        p1.typesSet = Collections.singleton("A");
